function initPersonalitiesPage(){const t=document.querySelectorAll(".category-tab"),e=document.querySelectorAll(".person-card");function a(t){e.forEach(e=>{e.getAttribute("data-category")===t?e.style.display="":e.style.display="none"})}t.forEach(e=>{e.addEventListener("click",()=>{t.forEach(t=>t.classList.remove("active")),e.classList.add("active"),a(e.getAttribute("data-category"))})}),a("historical")}